"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1935],{57291:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"OpeningTools","desc":"The tools that cut an opening into a plain wall: doorway, window, circle window, triangle window\\nand archway. The opening is centered on the cursor.\\n\\nWith the Set cut depth with mouse setting on, the first click fixes the spot and the mouse then\\nsets how deep the cut goes; past the far side it cuts all the way through. Otherwise one click\\ncuts through, as does a doorway with a frame or door, which only fit an opening that goes through.","source":{"line":13,"path":"src/Tools/Openings.luau"}}')}}]);